import { canvasScene } from "./core/canvas.js";
import { motionAllowed } from "./core/manager.js";
let instance, cleanup;
export function init(container, options = {}) {
  destroy();
  let source = [0.7, 0.5],
    third = [0.5, 0.5],
    clickTime = -100,
    time = 0;
  const buffer = document.createElement("canvas");
  buffer.width = 72;
  buffer.height = 112;
  const bctx = buffer.getContext("2d"),
    pixels = bctx.createImageData(72, 112);
  instance = canvasScene(
    container,
    ({ ctx, w, h, t, colors: c }) => {
      time = t;
      const aspect = w / h,
        rgb = c.cyan.match(/\w\w/g).map((v) => parseInt(v, 16)),
        strength = Math.max(0, 1 - (t - clickTime) / 2);
      for (let y = 0; y < 112; y++)
        for (let x = 0; x < 72; x++) {
          const u = x / 72,
            v = 1 - y / 112,
            d1 = Math.hypot((u - 0.3) * aspect, v - 0.52),
            d2 = Math.hypot((u - source[0]) * aspect, v - source[1]),
            d3 = Math.hypot((u - third[0]) * aspect, v - third[1]);
          const field =
            Math.sin(48 * d1 - t * 2.5) / Math.sqrt(1 + 3 * d1) +
            Math.sin(48 * d2 - t * 2.5) / Math.sqrt(1 + 3 * d2) +
            (strength * Math.sin(48 * d3 - t * 2.5)) / Math.sqrt(1 + 3 * d3);
          const index = (y * 72 + x) * 4;
          pixels.data[index] = rgb[0];
          pixels.data[index + 1] = rgb[1];
          pixels.data[index + 2] = rgb[2];
          pixels.data[index + 3] = 255 * (0.045 + 0.48 * (field / 3) ** 2);
        }
      bctx.putImageData(pixels, 0, 0);
      ctx.imageSmoothingEnabled = true;
      ctx.drawImage(buffer, 0, 0, w, h);
    },
    options,
  );
  const target = container.parentElement,
    coords = (e) => {
      const r = container.getBoundingClientRect();
      return [
        (e.clientX - r.left) / r.width,
        1 - (e.clientY - r.top) / r.height,
      ];
    };
  const move = (e) => {
    if (motionAllowed() && options.enabled !== false) {
      source = coords(e);
    }
  };
  const click = (e) => {
    if (
      motionAllowed() &&
      options.enabled !== false &&
      !e.target.closest("a,button")
    ) {
      third = coords(e);
      clickTime = time;
    }
  };
  target.addEventListener("pointermove", move, { passive: true });
  target.addEventListener("pointerdown", click, { passive: true });
  cleanup = () => {
    target.removeEventListener("pointermove", move);
    target.removeEventListener("pointerdown", click);
  };
  return instance;
}
export function destroy() {
  cleanup?.();
  instance?.destroy();
  instance = null;
}
